const V4_CSS = "\n        /* MVP_STUDIO_V4_MASTERING_REFINEMENT \u2014 desktop geometry + full responsive polish */\n        .tr-studioMeterGrid article i b{transition:width .18s ease-out!important}\n        .tr-dspProofStatus{align-items:center!important;gap:7px 9px!important}\n        .tr-studioProcessingPanel button,.tr-studioMeterGrid article{min-width:0!important}\n        .tr-dspAbControls .tr-dspBypassButton{white-space:nowrap!important}\n        @media(min-width:701px){\n          .tr-playerUtilityRow{align-items:end!important}\n          .tr-playerSourceTools{align-items:end!important}\n          .tr-playerSourceTools>.tr-audioQueueSelector{align-self:end!important}\n          .tr-playerSourceTools>.tr-dspStatusToggle{align-self:end!important;margin:0!important;height:50px!important;min-height:50px!important}\n          .tr-playerSourceTools .tr-audioQueueSelectorField{height:50px!important;min-height:50px!important}\n          .tr-studioMeterGrid{grid-template-columns:repeat(4,minmax(0,1fr))!important;gap:8px!important}\n        }\n        @media(max-width:700px){\n          .tr-audioEqPanel--pro7{width:calc(100% - 16px)!important;margin-left:auto!important;margin-right:auto!important;padding:10px!important;padding-bottom:104px!important;box-sizing:border-box!important}\n          .tr-outputProfilePanel{grid-template-columns:1fr!important;gap:11px!important}\n          .tr-outputProfileSelect{width:100%!important;max-width:none!important}\n          .tr-outputProfileChoices{grid-template-columns:repeat(2,minmax(0,1fr))!important;gap:8px!important}\n          .tr-outputProfileChoices button{min-height:46px!important}\n          .tr-outputProfileTelemetry{display:grid!important;grid-template-columns:repeat(2,minmax(0,1fr))!important;gap:7px!important}\n          .tr-sourceQualityPanel{grid-template-columns:1fr!important}\n          .tr-preampTrim{grid-template-columns:1fr!important;gap:10px!important;padding:12px!important}\n          .tr-preampTrimControl{width:100%!important;min-width:0!important}\n          .tr-preampAutoButton{width:100%!important;min-height:42px!important}\n          .tr-preampTrimScale{position:relative!important}\n          .tr-dspProofStatus{display:grid!important;grid-template-columns:repeat(2,minmax(0,1fr))!important;gap:7px!important}\n          .tr-dspProofStatus>span{min-width:0!important;white-space:normal!important;line-height:1.25!important}\n          .tr-studioMeterGrid{grid-template-columns:repeat(2,minmax(0,1fr))!important;gap:8px!important}\n          .tr-studioMeterGrid article{padding:10px!important;min-height:82px!important}\n          .tr-studioProcessingPanel{grid-template-columns:1fr!important;gap:8px!important}\n          .tr-studioProcessingPanel button{min-height:74px!important}\n          .tr-audioEqHead{grid-template-columns:1fr!important;gap:10px!important;align-items:stretch!important}\n          .tr-dspAbControls{display:grid!important;grid-template-columns:1fr 1fr!important;gap:8px!important;width:100%!important}\n          .tr-dspAbControls>*{width:100%!important;min-width:0!important}\n          .tr-audioEqPreset{width:100%!important;max-width:none!important}\n          .tr-audioEqPreset select{width:100%!important;min-height:44px!important}\n          .tr-eqArchitecturePanel{grid-template-columns:1fr!important;gap:10px!important}\n          .tr-eqArchitectureButtons{display:grid!important;grid-template-columns:1fr 1fr!important;gap:7px!important}\n          .tr-eqArchitectureButtons button{min-height:42px!important}\n          .tr-audioEqScroll{padding-bottom:8px!important;overscroll-behavior-inline:contain!important;scrollbar-width:thin!important}\n          .tr-audioEqBands--31{grid-template-columns:repeat(31,52px)!important;grid-auto-columns:52px!important;gap:7px!important;padding:0 8px!important}\n          .tr-audioEqBands--31 .tr-audioEqBand{width:52px!important;min-width:52px!important;max-width:52px!important;height:190px!important;grid-template-rows:25px 138px 16px!important}\n          .tr-audioEqBands--31 .tr-audioEqSliderShell{width:52px!important;min-width:52px!important;max-width:52px!important;height:138px!important}\n          .tr-audioEqBands--31 .tr-audioEqSliderShell input[type=\"range\"]{width:122px!important;min-width:122px!important;max-width:122px!important;height:22px!important}\n          .tr-audioEqBands--31 .tr-audioEqGain{font-size:8px!important}\n          .tr-audioEqBands--31 .tr-audioEqFrequency{font-size:8.5px!important}\n        }\n        @media(max-width:430px){\n          .tr-audioEqPanel--pro7{width:calc(100% - 10px)!important;padding:8px!important;padding-bottom:108px!important}\n          .tr-playerUtilityRow{gap:10px!important}\n          .tr-outputProfileTelemetry{grid-template-columns:1fr 1fr!important}\n          .tr-dspProofStatus{grid-template-columns:1fr!important}\n          .tr-studioMeterGrid{grid-template-columns:1fr!important}\n          .tr-studioMeterGrid article{min-height:76px!important}\n          .tr-dspAbControls{grid-template-columns:1fr 1fr!important}\n          .tr-dspAbControls .tr-audioEqSwitch,.tr-dspAbControls .tr-dspBypassButton{min-height:42px!important}\n          .tr-eqArchitectureButtons{grid-template-columns:1fr 1fr!important}\n          .tr-outputProfileChoices button{min-height:48px!important;font-size:9px!important}\n          .tr-sourceQualityCopy>strong{white-space:normal!important;line-height:1.2!important}\n        }\n";

function fail(message) {
  console.error(`\nMVP Studio V4 installer stopped: ${message}`);
  console.error("Nothing was committed. Fix the reported baseline mismatch and run the installer again.\n");
  process.exit(1);
}
function normalizeEol(text) { return text.replace(/\r\n/g, "\n"); }
function detectEol(text) { return text.includes("\r\n") ? "\r\n" : "\n"; }
function restoreEol(text, eol) { return eol === "\r\n" ? text.replace(/\n/g, "\r\n") : text; }
function readText(file) {
  if (!fs.existsSync(file)) fail(`Missing required file: ${path.relative(root, file)}`);
  const raw = fs.readFileSync(file, "utf8");
  return { text: normalizeEol(raw), eol: detectEol(raw) };
}
function backup(file) {
  const target = file + BACKUP_SUFFIX;
  if (fs.existsSync(file) && !fs.existsSync(target)) fs.copyFileSync(file, target);
}
function replaceSection(text, startNeedle, endNeedle, replacement, label) {
  const start = text.indexOf(startNeedle);
  if (start < 0) fail(`${label} start anchor not found.`);
  const end = text.indexOf(endNeedle, start);
  if (end < 0) fail(`${label} end anchor not found.`);
  if (text.indexOf(startNeedle, start + startNeedle.length) >= 0) fail(`${label} start anchor was ambiguous.`);
  return text.slice(0, start) + replacement + text.slice(end);
}
function replaceOnce(text, oldText, newText, label) {
  const first = text.indexOf(oldText);
  if (first < 0) fail(`${label} anchor not found.`);
  if (text.indexOf(oldText, first + oldText.length) >= 0) fail(`${label} anchor was ambiguous.`);
  return text.slice(0, first) + newText + text.slice(first + oldText.length);
}

for (const file of Object.values(paths)) if (!fs.existsSync(file)) fail(`Missing required baseline file: ${path.relative(root, file)}`);
const playerRead = readText(paths.player);
const miniRead = readText(paths.mini);
let player = playerRead.text;
let mini = miniRead.text;

if (player.includes(PHASE_MARKER) || mini.includes(PHASE_MARKER)) {
  console.log(`MVP Studio V4 Mastering Refinement is already applied. (${INSTALLER_REVISION})`);
  process.exit(0);
}
if (!player.includes("MVP_STUDIO_WASM_V3_PHASE6_STEREO_INTEGRITY")) fail("V3 Phase 6 Stereo Integrity baseline was not found in musicPlayer.ts.");
if (!mini.includes("LIVE DSP METERING") || !mini.includes("STEREO FIELD") || !mini.includes("WASM • BS.1770 TRUE PEAK")) fail("Phase 5/6 telemetry UI baseline was not found.");
if (!mini.includes("LINEAR PHASE • STUDIO WASM")) fail("Studio Linear Phase baseline was not found.");

// 1) Smooth the visible 31-band preset curves. These remain the tonal source of truth.
player = replaceSection(player, "export const MUSIC_EQ_PRESETS", "\ntype ProPeak", EQ_BLOCK, "31-band preset block");

// 2) Replace legacy hidden tonal definitions with transient-only preset personalities,
// then add the V4 processor-intensity map. No second hidden EQ curve is layered in Studio.
player = replaceSection(player, "const MUSIC_PRO_PRESETS", "\n// Output profiles are technical device paths", PRO_BLOCK, "Studio preset personality block");

// 3) Drive the existing Studio processors from the selected preset personality.
const transientOld = `  const studioTransientAmount = processed && state.eqEnabled
    ? Math.max(0, Math.min(1, currentTransientAmount() * sourceTransientScale()))
    : 0;`;
const transientNew = `  const studioPersonality = currentStudioPersonality();
  const studioTransientAmount = processed && state.eqEnabled
    ? Math.max(0, Math.min(1, currentTransientAmount() * sourceTransientScale() * studioPersonality.transientScale))
    : 0;`;
player = replaceOnce(player, transientOld, transientNew, "Studio transient personality");
player = replaceOnce(player, "    multibandAmount: 1,", "    multibandAmount: studioPersonality.multibandAmount,", "Multiband personality amount");
player = replaceOnce(player, "    dynamicEqAmount: 0.72,", "    dynamicEqAmount: studioPersonality.dynamicEqAmount,", "Dynamic EQ personality amount");
player = replaceOnce(player, "    outputCorrectionAmount: 1,", "    outputCorrectionAmount: studioPersonality.outputCorrectionAmount,", "Output Correction personality amount");
player = replaceOnce(player, "    stereoIntegrityAmount: 1,", "    stereoIntegrityAmount: studioPersonality.stereoIntegrityAmount,", "Stereo Integrity personality amount");

// 4) Make the already gain-matched Reference route explicit in the UI.
const abOld = `>REFERENCE {player.dspBypass || player.outputProfile === "reference" ? "ACTIVE" : "A/B"}</button>`;
const abNew = `>GAIN-MATCH {player.dspBypass || player.outputProfile === "reference" ? "REFERENCE" : "A/B"}</button>`;
if (mini.includes(abOld)) mini = replaceOnce(mini, abOld, abNew, "Gain-matched A/B label");
else if (mini.includes(">REFERENCE A/B</button>")) mini = replaceOnce(mini, ">REFERENCE A/B</button>", ">GAIN-MATCH A/B</button>", "Gain-matched A/B fallback label");

// 5) Desktop alignment + full mobile/responsive refinement.
const styleEnd = "      `}</style>";
if (!mini.includes(styleEnd)) fail("Music player style terminator was not found.");
mini = replaceOnce(mini, styleEnd, V4_CSS + "      `}</style>", "V4 responsive CSS insertion");

const nextWasm = Buffer.from(payload.wasmBase64, "base64");
if (nextWasm.length < 59000 || nextWasm[0] !== 0x00 || nextWasm[1] !== 0x61 || nextWasm[2] !== 0x73 || nextWasm[3] !== 0x6d) fail("Packaged V4 WASM binary failed integrity check.");
try { new WebAssembly.Module(nextWasm); } catch (error) { fail(`Packaged V4 WASM compile check failed: ${error instanceof Error ? error.message : String(error)}`); }

// Validate all edits before touching disk.
for (const needle of [PHASE_MARKER, "studioPersonality.multibandAmount", "studioPersonality.dynamicEqAmount", "studioPersonality.outputCorrectionAmount", "studioPersonality.stereoIntegrityAmount"]) {
  if (!player.includes(needle)) fail(`Preflight verification failed for ${needle}.`);
}
if (!mini.includes("MVP_STUDIO_V4_MASTERING_REFINEMENT")) fail("V4 UI preflight verification failed.");

for (const file of Object.values(paths)) backup(file);
fs.writeFileSync(paths.engine, payload.engine, "utf8");
fs.writeFileSync(paths.worklet, payload.worklet, "utf8");
fs.writeFileSync(paths.cpp, payload.cpp, "utf8");
fs.writeFileSync(paths.build, payload.build, "utf8");
fs.writeFileSync(paths.test, payload.test, "utf8");
fs.writeFileSync(paths.wasm, nextWasm);
fs.writeFileSync(paths.player, restoreEol(player, playerRead.eol), "utf8");
fs.writeFileSync(paths.mini, restoreEol(mini, miniRead.eol), "utf8");

console.log(`MVP Studio V4 Mastering + UI Refinement applied successfully. (${INSTALLER_REVISION})`);
console.log("Refined:");
console.log("  • smoother 31-band curves across every built-in preset");
console.log("  • preset-aware Transient / Multiband / Dynamic EQ / Output Correction / Stereo Integrity");
console.log("  • lighter mastering-style multiband and Dynamic EQ thresholds");
console.log("  • more transparent Output Correction and Stereo Integrity");
console.log("  • closer Minimum/Linear Phase tonal matching");
console.log("  • existing gain-matched Reference A/B made explicit");
console.log("  • desktop DSP/EQ alignment + full mobile responsive polish");
console.log("Preserved: Volume Match OFF-by-default • BS.1770 True Peak • Live DSP Metering • Compatibility fallback");
console.log(`Backups: *${BACKUP_SUFFIX}`);
console.log("NEXT: run npm run build");
